90	/// Minimal, strict DER decoder and the slice of X.509 needed by `inspect`.
91	mod x509 {
92	    use std::fmt::Write;
93	
94	    pub(super) struct Cert {
95	        pub(super) subject: String,
96	        pub(super) issuer: String,
97	        pub(super) serial_hex: String,
98	        pub(super) not_before: String,
99	        pub(super) not_after: String,
100	    }
101	
102	    #[derive(Clone, Copy)]
103	    struct Tlv<'a> {
104	        tag: u8,
105	        content: &'a [u8],
106	    }
107	
108	    const TAG_INTEGER: u8 = 0x02;
109	    const TAG_BIT_STRING: u8 = 0x03;
110	    const TAG_OCTET_STRING: u8 = 0x04;
111	    const TAG_BOOLEAN: u8 = 0x01;
112	    const TAG_OID: u8 = 0x06;
113	    const TAG_SEQUENCE: u8 = 0x30;
114	    const TAG_SET: u8 = 0x31;
115	    const TAG_UTC_TIME: u8 = 0x17;
116	    const TAG_GENERALIZED_TIME: u8 = 0x18;
117	
118	    /// Read exactly one DER TLV. Rejects indefinite length, non-minimal
119	    /// length encodings and truncated data.
120	    fn read_tlv(buf: &[u8]) -> Result<(Tlv<'_>, &[u8]), String> {
121	        let tag = *buf.first().ok_or_else(|| "unexpected end of data".to_string())?;
122	        if tag & 0x1F == 0x1F {
123	            return Err("multi-byte tags are not supported".to_string());
124	        }
125	        let first_len = *buf.get(1).ok_or_else(|| "truncated length".to_string())?;
126	        let (len, header_len) = match first_len {
127	            0x00..=0x7F => (first_len as usize, 2),
128	            0x80 => return Err("indefinite length is not valid DER".to_string()),
129	            0xFF => return Err("reserved length byte".to_string()),
130	            long => {
131	                let n = (long & 0x7F) as usize;
132	                if !(1..=4).contains(&n) {
133	                    return Err("length is too large".to_string());
134	                }
135	                let bytes = buf
136	                    .get(2..2 + n)
137	                    .ok_or_else(|| "truncated long length".to_string())?;
138	                if bytes[0] == 0 {
139	                    return Err("non-minimal length encoding".to_string());
140	                }
141	                let mut len = 0usize;
142	                for &b in bytes {
143	                    len = len
144	                        .checked_shl(8)
145	                        .and_then(|l| l.checked_add(b as usize))
146	                        .ok_or_else(|| "length overflow".to_string())?;
147	                }
148	                if len < 0x80 {
149	                    return Err("non-minimal length encoding".to_string());
150	                }
151	                (len, 2 + n)
152	            }
153	        };
154	        let total = header_len
155	            .checked_add(len)
156	            .filter(|&t| t <= buf.len())
157	            .ok_or_else(|| "truncated TLV content".to_string())?;
158	        Ok((
159	            Tlv {
160	                tag,
161	                content: &buf[header_len..total],
162	            },
163	            &buf[total..],
164	        ))
165	    }
166	
167	    fn read_tagged<'a>(
168	        buf: &'a [u8],
169	        tag: u8,
170	        what: &str,
171	    ) -> Result<(Tlv<'a>, &'a [u8]), String> {
172	        let (tlv, rest) = read_tlv(buf).map_err(|e| format!("{what}: {e}"))?;
173	        if tlv.tag != tag {
174	            return Err(format!("expected {what} (tag 0x{tag:02X}), got 0x{:02X}", tlv.tag));
175	        }
176	        Ok((tlv, rest))
177	    }
178	
179	    pub(super) fn parse(bytes: &[u8]) -> Result<Cert, String> {
180	        // Certificate ::= SEQUENCE { tbsCertificate, signatureAlgorithm,
181	        // signatureValue BIT STRING } — and nothing trailing.
182	        let (cert, rest) = read_tagged(bytes, TAG_SEQUENCE, "Certificate SEQUENCE")?;
183	        if !rest.is_empty() {
184	            return Err(format!("{} trailing byte(s) after certificate", rest.len()));
185	        }
186	
187	        let c = cert.content;
188	        let (tbs, c) = read_tagged(c, TAG_SEQUENCE, "tbsCertificate")?;
189	        let (outer_alg, c) = read_tagged(c, TAG_SEQUENCE, "outer signatureAlgorithm")?;
190	        let outer_alg = parse_signature_algorithm(outer_alg, "outer signatureAlgorithm")?;
191	        let (sig_value, c) = read_tlv(c)?;
192	        if sig_value.tag != TAG_BIT_STRING {
193	            return Err("signature must be a BIT STRING".to_string());
194	        }
195	        if sig_value.content.is_empty() || sig_value.content[0] > 7 {
196	            return Err("invalid signature BIT STRING".to_string());
197	        }
198	        if !c.is_empty() {
199	            return Err("trailing data in Certificate".to_string());
200	        }
201	
202	        // TBSCertificate ::= SEQUENCE {
203	        //   version [0] EXPLICIT Version DEFAULT v1, serialNumber, signature,
204	        //   issuer, validity, subject, subjectPublicKeyInfo, ... }
205	        let t = tbs.content;
206	        let (first, t2) = read_tlv(t)?;
207	        let (version, t) = if first.tag == 0xA0 {
208	            let (ver, vrest) = read_tagged(first.content, TAG_INTEGER, "version")?;
209	            if !vrest.is_empty() || ver.content.len() != 1 || ver.content[0] > 2 {
210	                return Err("invalid certificate version".to_string());
211	            }
212	            (ver.content[0], t2)
213	        } else {
214	            // No explicit version: v1 certificate.
215	            (0u8, t)
216	        };
217	
218	        let (serial, t3) = read_tagged(t, TAG_INTEGER, "serialNumber")?;
219	        let t = t3;
220	        let (tbs_alg, t) = read_tagged(t, TAG_SEQUENCE, "tbs signatureAlgorithm")?;
221	        let tbs_alg = parse_signature_algorithm(tbs_alg, "tbs signatureAlgorithm")?;
222	        if tbs_alg != outer_alg {
223	            return Err(mismatch_message(&outer_alg, &tbs_alg));
224	        }
225	        let (issuer, t) = read_tagged(t, TAG_SEQUENCE, "issuer")?;
226	        let (validity, t) = read_tagged(t, TAG_SEQUENCE, "validity")?;
227	        let (subject, t) = read_tagged(t, TAG_SEQUENCE, "subject")?;
228	        let (spki, t_after_spki) = read_tagged(t, TAG_SEQUENCE, "subjectPublicKeyInfo")?;
229	        check_spki(spki)?;
230	        // Optional tail of TBSCertificate, in a fixed order:
231	        //   issuerUniqueID  [1] IMPLICIT BIT STRING  (v2/v3, at most once)
232	        //   subjectUniqueID [2] IMPLICIT BIT STRING  (v2/v3, at most once)
233	        //   extensions      [3] EXPLICIT             (v3 only, at most once,
234	        //                                             and the last field)
235	        // Nothing else may follow subjectPublicKeyInfo: fields cannot be
236	        // skipped, reordered or dropped. The extensions interior is decoded in
237	        // full by `check_extensions`; the unique IDs carry BIT STRING content
238	        // directly (implicit tagging), validated by `check_bit_string`.
239	        let mut t = t_after_spki;
240	        let mut issuer_uid_seen = false;
241	        let mut subject_uid_seen = false;
242	        let mut extensions_present = false;
243	        while !t.is_empty() {
244	            let tag_hint = t.first().copied();
245	            let (field, rest) = read_tlv(t).map_err(|e| match tag_hint {
246	                Some(0x81) => format!("issuerUniqueID: {e}"),
247	                Some(0x82) => format!("subjectUniqueID: {e}"),
248	                // A truncated field whose tag is already readable can still
249	                // be located: tag 0xA3 is the extensions field.
250	                Some(0xA3) => format!("extensions field: {e}"),
251	                _ => e,
252	            })?;
253	            match field.tag {
254	                0x81 | 0x82 => {
255	                    let what = if field.tag == 0x81 {
256	                        "issuerUniqueID"
257	                    } else {
258	                        "subjectUniqueID"
259	                    };
260	                    if version < 1 {
261	                        return Err(format!(
262	                            "{what} is only allowed in v2 or v3 certificates, this is v1"
263	                        ));
264	                    }
265	                    if extensions_present {
266	                        return Err(format!(
267	                            "{what} must appear before the extensions field, \
268	                             which is the last field of tbsCertificate"
269	                        ));
270	                    }
271	                    if field.tag == 0x81 {
272	                        if issuer_uid_seen {
273	                            return Err("duplicate issuerUniqueID field".to_string());
274	                        }
275	                        if subject_uid_seen {
276	                            return Err(
277	                                "issuerUniqueID must appear before subjectUniqueID".to_string()
278	                            );
279	                        }
280	                        issuer_uid_seen = true;
281	                    } else if subject_uid_seen {
282	                        return Err("duplicate subjectUniqueID field".to_string());
283	                    } else {
284	                        subject_uid_seen = true;
285	                    }
286	                    check_bit_string(field.content, what)?;
287	                }
288	                0xA1 | 0xA2 => {
289	                    let what = if field.tag == 0xA1 {
290	                        "issuerUniqueID"
291	                    } else {
292	                        "subjectUniqueID"
293	                    };
294	                    return Err(format!(
295	                        "{what} must be an implicitly tagged primitive BIT STRING \
296	                         (tag 0x{:02X}); constructed tag 0x{:02X} is an explicit wrapper \
297	                         and is not allowed",
298	                        field.tag - 0x20,
299	                        field.tag
300	                    ));
301	                }
302	                0xA3 => {
303	                    if extensions_present {
304	                        return Err("duplicate extensions field".to_string());
305	                    }
306	                    if version != 2 {
307	                        let name = if version == 0 {
308	                            "v1"
309	                        } else {
310	                            "v2"
311	                        };
312	                        return Err(format!(
313	                            "extensions are only allowed in v3 certificates, this is {name}"
314	                        ));
315	                    }
316	                    check_extensions(field.content)?;
317	                    extensions_present = true;
318	                }
319	                other => {
320	                    return Err(format!(
321	                        "unexpected field after subjectPublicKeyInfo (tag 0x{other:02X}): \
322	                         only issuerUniqueID [1], subjectUniqueID [2] and extensions [3] \
323	                         are allowed there, and extensions must be last"
324	                    ));
325	                }
326	            }
327	            t = rest;
328	        }
329	
330	        let serial_hex = format_serial(serial.content)?;
331	        let issuer = format_name(issuer, "issuer")?;
332	        let subject = format_name(subject, "subject")?;
333	
334	        let v = validity.content;
335	        let (nb, v2) = read_tlv(v)?;
336	        let (na, v3) = read_tlv(v2)?;
337	        if !v3.is_empty() {
338	            return Err("trailing data in validity".to_string());
339	        }
340	        let not_before = format_time(nb)?;
341	        let not_after = format_time(na)?;
342	
343	        Ok(Cert {
344	            subject,
345	            issuer,
346	            serial_hex,
347	            not_before,
348	            not_after,
349	        })
350	    }
351	
352	    /// Validate the content of the extensions field, i.e. the bytes wrapped
353	    /// by `[3] EXPLICIT`:
354	    ///
355	    /// ```text
356	    /// Extensions ::= SEQUENCE SIZE (1..MAX) OF Extension
357	    /// Extension  ::= SEQUENCE {
358	    ///   extnID    OBJECT IDENTIFIER,
359	    ///   critical  BOOLEAN DEFAULT FALSE,
360	    ///   extnValue OCTET STRING }
361	    /// ```
362	    ///
363	    /// The wrapper must contain exactly one non-empty Extensions SEQUENCE.
364	    /// Every extension must contain its OID and OCTET STRING in that order,
365	    /// with at most one (DER-encoded) BOOLEAN between them and nothing after.
366	    /// Extension contents are never interpreted: unknown but well-formed
367	    /// extension OIDs are accepted and `critical: TRUE` is not a failure.
368	    fn check_extensions(wrapper: &[u8]) -> Result<(), String> {
369	        let (list, rest) = read_tagged(wrapper, TAG_SEQUENCE, "extensions")?;
370	        if !rest.is_empty() {
371	            return Err("extensions wrapper contains data after the Extensions SEQUENCE".to_string());
372	        }
373	        if list.content.is_empty() {
374	            return Err("extensions SEQUENCE is empty".to_string());
375	        }
376	
377	        let mut buf = list.content;
378	        while !buf.is_empty() {
379	            let (ext, rest) = read_tagged(buf, TAG_SEQUENCE, "extension")?;
380	            buf = rest;
381	
382	            let (oid, after_oid) = read_tagged(ext.content, TAG_OID, "extension OID")?;
383	            parse_oid(oid.content).map_err(|e| format!("extension OID: {e}"))?;
384	
385	            // critical is optional; whatever stands between the OID and the
386	            // OCTET STRING must be exactly one BOOLEAN if it is present.
387	            let (maybe_bool, after_critical) = read_tlv(after_oid)
388	                .map_err(|e| format!("extension after OID: {e}"))?;
389	            let (octets, after_octets) = if maybe_bool.tag == TAG_BOOLEAN {
390	                match maybe_bool.content {
391	                    [0xFF] => {}
392	                    [0x00] => {
393	                        return Err(
394	                            "extension critical: explicit DER encoding of DEFAULT FALSE is not allowed"
395	                                .to_string()
396	                        )
397	                    }
398	                    _ => {
399	                        return Err(
400	                            "extension critical: invalid DER encoding of BOOLEAN".to_string()
401	                        )
402	                    }
403	                }
404	                read_tagged(after_critical, TAG_OCTET_STRING, "extension value")?
405	            } else {
406	                // Not a BOOLEAN: this element must itself be the extnValue.
407	                if maybe_bool.tag != TAG_OCTET_STRING {
408	                    return Err(format!(
409	                        "extension must contain a critical BOOLEAN then an OCTET STRING, \
410	                         got tag 0x{:02X}",
411	                        maybe_bool.tag
412	                    ));
413	                }
414	                (maybe_bool, after_critical)
415	            };
416	            // An empty OCTET STRING is legal; its bytes are not interpreted.
417	            let _ = octets.content;
418	            if !after_octets.is_empty() {
419	                return Err("trailing data in extension".to_string());
420	            }
421	        }
422	        Ok(())
423	    }
424	
425	    /// SubjectPublicKeyInfo ::= SEQUENCE {
426	    ///   algorithm        AlgorithmIdentifier,
427	    ///   subjectPublicKey BIT STRING }
428	    /// Nothing may be missing and no extra elements may follow.
429	    fn check_spki(spki: Tlv) -> Result<(), String> {
430	        let (alg, rest) = read_tagged(
431	            spki.content,
432	            TAG_SEQUENCE,
433	            "subjectPublicKeyInfo algorithm identifier",
434	        )?;
435	        check_algorithm_identifier(alg)?;
436	        let (key, rest) = read_tagged(rest, TAG_BIT_STRING, "subjectPublicKey")?;
437	        check_bit_string(key.content, "subjectPublicKey")?;
438	        if !rest.is_empty() {
439	            return Err("trailing data in subjectPublicKeyInfo".to_string());
440	        }
441	        Ok(())
442	    }
443	
444	    /// AlgorithmIdentifier ::= SEQUENCE {
445	    ///   algorithm  OBJECT IDENTIFIER,
446	    ///   parameters ANY DEFINED BY algorithm OPTIONAL }
447	    /// The parameters, if present, must be exactly one complete DER TLV;
448	    /// absent parameters and an explicit NULL are both accepted. The
449	    /// parameter content is not interpreted for any particular algorithm.
450	    fn check_algorithm_identifier(alg: Tlv) -> Result<(), String> {
451	        let (oid, rest) = read_tagged(alg.content, TAG_OID, "algorithm OID")?;
452	        parse_oid(oid.content).map_err(|e| format!("algorithm OID: {e}"))?;
453	        if rest.is_empty() {
454	            return Ok(());
455	        }
456	        let (_params, after) =
457	            read_tlv(rest).map_err(|e| format!("algorithm parameters: {e}"))?;
458	        if !after.is_empty() {
459	            return Err("multiple algorithm parameters".to_string());
460	        }
461	        Ok(())
462	    }
463	
464	    /// One of the certificate's two signature algorithm descriptions, kept as
465	    /// raw slices so two copies can be compared at the DER byte level: the OID
466	    /// content (arcs in their shortest encoding) and the complete parameter
467	    /// TLV (tag, length and content), or no parameter at all. An absent
468	    /// parameter and an explicit NULL are different representations.
469	    #[derive(Clone, Copy, PartialEq, Eq)]
470	    struct SignatureAlgorithm<'a> {
471	        oid_content: &'a [u8],
472	        params: Option<&'a [u8]>,
473	    }
474	
475	    /// Parse and fully validate one signatureAlgorithm SEQUENCE: it must start
476	    /// with one complete, shortest-encoded algorithm OID, followed by either
477	    /// nothing or exactly one complete DER parameter value. `loc` names which
478	    /// of the two copies is being checked ("outer signatureAlgorithm" or the
479	    /// copy inside tbsCertificate) and prefixes every error message.
480	    fn parse_signature_algorithm<'a>(
481	        alg: Tlv<'a>,
482	        loc: &str,
483	    ) -> Result<SignatureAlgorithm<'a>, String> {
484	        let (oid, rest) = read_tlv(alg.content).map_err(|e| format!("{loc}: {e}"))?;
485	        if oid.tag != TAG_OID {
486	            return Err(format!(
487	                "{loc}: algorithm must start with an OID (tag 0x06), got tag 0x{:02X}",
488	                oid.tag
489	            ));
490	        }
491	        // Validates the OID content itself: non-empty, complete base-128 arcs
492	        // in their shortest encoding.
493	        parse_oid(oid.content).map_err(|e| format!("{loc}: {e}"))?;
494	        let params = if rest.is_empty() {
495	            None
496	        } else {
497	            let (_param, after) = read_tlv(rest)
498	                .map_err(|e| format!("{loc}: algorithm parameters: {e}"))?;
499	            if !after.is_empty() {
500	                return Err(format!(
501	                    "{loc}: extra element after the algorithm parameters"
502	                ));
503	            }
504	            // Keep the full parameter TLV (tag, length and content), sliced
505	            // straight from the enclosing content; `read_tlv` already proved
506	            // it is a complete value.
507	            let param_len = rest.len() - after.len();
508	            Some(&rest[..param_len])
509	        };
510	        Ok(SignatureAlgorithm {
511	            oid_content: oid.content,
512	            params,
513	        })
514	    }
515	
516	    /// Describe the disagreement between the outer signatureAlgorithm and the
517	    /// copy inside tbsCertificate. Both copies parse on their own; they merely
518	    /// fail to name the same algorithm or the same parameter representation.
519	    fn mismatch_message(outer: &SignatureAlgorithm<'_>, inner: &SignatureAlgorithm<'_>) -> String {
520	        const OUTER: &str = "the outer signatureAlgorithm";
521	        const INNER: &str = "the signatureAlgorithm in tbsCertificate";
522	        if outer.oid_content != inner.oid_content {
523	            let outer_oid = parse_oid(outer.oid_content)
524	                .map(|arcs| arcs_to_string(&arcs))
525	                .unwrap_or_else(|_| "?".to_string());
526	            let inner_oid = parse_oid(inner.oid_content)
527	                .map(|arcs| arcs_to_string(&arcs))
528	                .unwrap_or_else(|_| "?".to_string());
529	            return format!(
530	                "signature algorithm mismatch: {OUTER} names OID {outer_oid}, but {INNER} \
531	                 names OID {inner_oid}"
532	            );
533	        }
534	        match (outer.params, inner.params) {
535	            (Some(outer_params), Some(inner_params)) if outer_params != inner_params => {
536	                format!(
537	                    "signature algorithm mismatch: both copies name the same algorithm OID but \
538	                     their parameters have different DER encodings ({OUTER} has {}, {INNER} has {})",
539	                    hex_of(outer_params),
540	                    hex_of(inner_params),
541	                )
542	            }
543	            (Some(_), None) => format!(
544	                "signature algorithm mismatch: {OUTER} carries parameters but {INNER} omits them \
545	                 (an absent parameter and an explicit value are different representations)"
546	            ),
547	            (None, Some(_)) => format!(
548	                "signature algorithm mismatch: {INNER} carries parameters but {OUTER} omits them \
549	                 (an absent parameter and an explicit value are different representations)"
550	            ),
551	            // PartialEq already proved the copies unequal; reaching any other
552	            // arm here would be a logic error rather than a malformed cert.
553	            _ => "signature algorithm mismatch between the two signatureAlgorithm copies"
554	                .to_string(),
555	        }
556	    }
557	
558	    fn hex_of(bytes: &[u8]) -> String {
559	        let mut s = String::with_capacity(bytes.len() * 2);
560	        for b in bytes {
561	            write!(s, "{b:02X}").unwrap();
562	        }
563	        s
564	    }
565	
566	    /// Validate the DER content of a BIT STRING: one leading byte counting
567	    /// unused bits (0..=7), and when the count is nonzero those low bits of
568	    /// the final data byte must all be zero. An empty bit string is only
569	    /// legal with a zero count.
570	    fn check_bit_string(content: &[u8], what: &str) -> Result<(), String> {
571	        let unused = *content
572	            .first()
573	            .ok_or_else(|| format!("{what} BIT STRING is missing the unused-bits byte"))?;
574	        if unused > 7 {
575	            return Err(format!("{what} BIT STRING has invalid unused-bits count {unused}"));
576	        }
577	        let data = &content[1..];
578	        if data.is_empty() {
579	            if unused != 0 {
580	                return Err(format!(
581	                    "{what} BIT STRING declares {unused} unused bits but has no data"
582	                ));
583	            }
584	            return Ok(());
585	        }
586	        if unused != 0 && data[data.len() - 1] & ((1u8 << unused) - 1) != 0 {
587	            return Err(format!(
588	                "{what} BIT STRING has set bits among the {unused} unused trailing bits"
589	            ));
590	        }
591	        Ok(())
592	    }
593	
594	    /// Render the serial number as upper-case hex, matching the integer value
595	    /// (a DER sign-padding 0x00 byte is not part of the number).
596	    fn format_serial(content: &[u8]) -> Result<String, String> {
597	        if content.is_empty() {
598	            return Err("empty serial number".to_string());
599	        }
600	        if content.len() > 1 && content[0] == 0xFF && content[1] & 0x80 == 0 {
601	            return Err("non-minimal serial number encoding".to_string());
602	        }
603	        if content.len() > 1 && content[0] == 0x00 && content[1] & 0x80 == 0 {
604	            return Err("non-minimal serial number encoding".to_string());
605	        }
606	        if content[0] & 0x80 != 0 && !(content.len() > 1 && content[0] == 0x00) {
607	            return Err("negative serial number".to_string());
608	        }
609	        let digits = if content.len() > 1 && content[0] == 0x00 {
610	            &content[1..]
611	        } else {
612	            content
613	        };
614	        let mut s = String::with_capacity(digits.len() * 2);
615	        for b in digits {
616	            write!(s, "{b:02X}").unwrap();
617	        }
618	        if s.is_empty() {
619	            s.push_str("00");
620	        }
621	        Ok(s)
622	    }
623	
624	    /// Name ::= SEQUENCE OF RDN; rendered per RFC 4514 (RDNs reversed,
625	    /// multi-valued RDNs joined with '+'). Values of known attribute types
626	    /// are emitted as real UTF-8 text (non-ASCII content preserved verbatim)
627	    /// when their tag has a text decoder; a known type carrying any other
628	    /// readable DER value (e.g. postalAddress as a SEQUENCE) keeps its short
629	    /// name and uses the '#' form carrying the value's full DER encoding in
630	    /// hex. Attributes without a known short name use their dotted OID with
631	    /// the same '#' form.
632	    ///
633	    /// Each RDN is a DER SET OF, so its complete AttributeTypeAndValue
634	    /// encodings must be sorted by their full encoding bytes (tag, then
635	    /// length, then content — the encoding, never the display name, dotted
636	    /// OID text or decoded value). The check is per RDN; it never reorders
637	    /// the members itself. `what` names the name being checked ("subject" or
638	    /// "issuer") so an ordering failure identifies it in the error message.
639	    fn format_name(name: Tlv, what: &str) -> Result<String, String> {
640	        let mut rdn_buf = name.content;
641	        let mut rdns: Vec<String> = Vec::new();
642	        while !rdn_buf.is_empty() {
643	            let (set, rest) = read_tagged(rdn_buf, TAG_SET, "RelativeDistinguishedName")?;
644	            rdn_buf = rest;
645	
646	            let mut atv_buf = set.content;
647	            let mut parts = Vec::new();
648	            // Raw full encoding (tag, length and content) of each member of
649	            // this SET OF, straight from the certificate: DER SET OF ordering
650	            // compares the complete member encodings byte for byte. Equal
651	            // encodings may legitimately repeat and stay adjacent.
652	            let mut members: Vec<&[u8]> = Vec::new();
653	            while !atv_buf.is_empty() {
654	                let atv_start = atv_buf;
655	                let (atv, rest) =
656	                    read_tagged(atv_buf, TAG_SEQUENCE, "AttributeTypeAndValue")?;
657	                atv_buf = rest;
658	                members.push(&atv_start[..atv_start.len() - atv_buf.len()]);
659	
660	                let (oid, after_oid) = read_tagged(atv.content, TAG_OID, "attribute OID")?;
661	                let (value, after_value) = read_tlv(after_oid)?;
662	                if !after_value.is_empty() {
663	                    return Err("trailing data in attribute value".to_string());
664	                }
665	
666	                let oid_arcs = parse_oid(oid.content)?;
667	                match oid_short_name(&oid_arcs) {
668	                    Some(label) => {
669	                        if is_text_value_tag(value.tag) {
670	                            // Supported string type: decode to escaped text.
671	                            // A decode failure (e.g. invalid UTF-8) means the
672	                            // certificate is corrupt; it must not be salvaged
673	                            // by falling back to the hex form.
674	                            let text = decode_attribute_value(value.tag, value.content)?;
675	                            parts.push(format!("{label}={}", escape_value(&text)));
676	                        } else {
677	                            // Known type but a legal value with no text decoder
678	                            // (SEQUENCE, OCTET STRING, ...): keep the short name
679	                            // and show the full original DER encoding as '#'-hex.
680	                            parts.push(format!("{label}=#{}", value_hex(after_oid, after_value)));
681	                        }
682	                    }
683	                    None => {
684	                        // Unknown attribute type: RFC 4514 requires the form
685	                        // OID=#hex, where the hex is the full DER encoding
686	                        // (tag, length and content) of the attribute value.
687	                        // The value is still validated: a UTF8String must
688	                        // hold valid UTF-8 even when shown as hex.
689	                        if value.tag == 0x0C {
690	                            std::str::from_utf8(value.content)
691	                                .map_err(|_| "invalid UTF-8 in UTF8String".to_string())?;
692	                        }
693	                        let hex = value_hex(after_oid, after_value);
694	                        parts.push(format!("{}=#{hex}", arcs_to_string(&oid_arcs)));
695	                    }
696	                }
697	            }
698	            if parts.is_empty() {
699	                return Err("empty RelativeDistinguishedName".to_string());
700	            }
701	            check_rdn_der_order(&members, what)?;
702	            rdns.push(parts.join("+"));
703	        }
704	        rdns.reverse();
705	        Ok(rdns.join(","))
706	    }
707	
708	    /// Validate one RDN as a DER SET OF: every member's complete
709	    /// AttributeTypeAndValue encoding must be less than or equal to the next
710	    /// one under ordinary byte ordering of tag, length and content. The
711	    /// comparison runs on the raw encodings only — CN/O short names, dotted
712	    /// OID text and decoded values never enter into it — and equal adjacent
713	    /// members (duplicate attributes) are allowed. The members are never
714	    /// reordered to make an unsorted input pass. `what` is "subject" or
715	    /// "issuer" and identifies the offending name in the error message.
716	    fn check_rdn_der_order(members: &[&[u8]], what: &str) -> Result<(), String> {
717	        for pair in members.windows(2) {
718	            if pair[0] > pair[1] {
719	                return Err(format!(
720	                    "{what} name: attributes of a multi-valued RelativeDistinguishedName \
721	                     are not encoded in DER SET OF order (the members must be sorted by \
722	                     their complete DER encoding bytes: tag, then length, then content)"
723	                ));
724	            }
725	        }
726	        Ok(())
727	    }
728	
729	    /// Uppercase hex of one complete value TLV, sliced straight from the
730	    /// input bytes (`around` ends at `rest`). The original tag and length
731	    /// bytes survive verbatim, including a legal long-form length; nothing is
732	    /// re-encoded and content alone is never emitted.
733	    fn value_hex(around: &[u8], rest: &[u8]) -> String {
734	        let tlv_len = around.len() - rest.len();
735	        let mut hex = String::with_capacity(tlv_len * 2);
736	        for b in &around[..tlv_len] {
737	            write!(hex, "{b:02X}").unwrap();
738	        }
739	        hex
740	    }
741	
742	    /// Tags whose attribute values have a direct text decoding in
743	    /// `decode_attribute_value`. Every other tag that `read_tlv` accepts is a
744	    /// legal non-text value for display purposes and is rendered as '#'-hex.
745	    fn is_text_value_tag(tag: u8) -> bool {
746	        matches!(
747	            tag,
748	            0x0C | 0x12 | 0x13 | 0x14 | 0x16 | 0x1A | 0x1B | 0x1C | 0x1E
749	        )
750	    }
751	
752	    fn parse_oid(content: &[u8]) -> Result<Vec<u64>, String> {
753	        if content.is_empty() {
754	            return Err("empty OID".to_string());
755	        }
756	        let mut arcs = Vec::new();
757	        // The first subidentifier encodes the first two arcs as
758	        // 40*first + second and is itself a base-128 quantity, so it can
759	        // span multiple content bytes (e.g. 2.999 encodes as 0x88 0x37).
760	        let mut i = 0;
761	        let first = read_oid_arc(content, &mut i)?;
762	        match first {
763	            0..=39 => {
764	                arcs.push(0);
765	                arcs.push(first);
766	            }
767	            40..=79 => {
768	                arcs.push(1);
769	                arcs.push(first - 40);
770	            }
771	            _ => {
772	                arcs.push(2);
773	                arcs.push(first - 80);
774	            }
775	        }
776	        while i < content.len() {
777	            arcs.push(read_oid_arc(content, &mut i)?);
778	        }
779	        Ok(arcs)
780	    }
781	
782	    /// Read one base-128 subidentifier starting at `*i`. Rejects trailing
783	    /// continuation bytes and non-minimal encodings.
784	    fn read_oid_arc(content: &[u8], i: &mut usize) -> Result<u64, String> {
785	        let start = *i;
786	        let mut value = 0u64;
787	        loop {
788	            let b = *content
789	                .get(*i)
790	                .ok_or_else(|| "truncated OID arc".to_string())?;
791	            value = value
792	                .checked_mul(128)
793	                .and_then(|v| v.checked_add((b & 0x7F) as u64))
794	                .ok_or_else(|| "OID arc overflow".to_string())?;
795	            *i += 1;
796	            if b & 0x80 == 0 {
797	                break;
798	            }
799	        }
800	        if *i - start > 1 && content[start] == 0x80 {
801	            return Err("non-minimal OID arc encoding".to_string());
802	        }
803	        Ok(value)
804	    }
805	
806	    fn arcs_to_string(arcs: &[u64]) -> String {
807	        arcs.iter()
808	            .map(u64::to_string)
809	            .collect::<Vec<_>>()
810	            .join(".")
811	    }
812	
813	    fn oid_short_name(arcs: &[u64]) -> Option<&'static str> {
814	        // X.520 / X.521 (2.5.4.*) and the commonly used LDAP/PKCS names.
815	        let name = match arcs {
816	            [2, 5, 4, 3] => "CN",
817	            [2, 5, 4, 4] => "SN",
818	            [2, 5, 4, 5] => "serialNumber",
819	            [2, 5, 4, 6] => "C",
820	            [2, 5, 4, 7] => "L",
821	            [2, 5, 4, 8] => "ST",
822	            [2, 5, 4, 9] => "STREET",
823	            [2, 5, 4, 10] => "O",
824	            [2, 5, 4, 11] => "OU",
825	            [2, 5, 4, 12] => "title",
826	            [2, 5, 4, 17] => "postalAddress",
827	            [2, 5, 4, 18] => "postalCode",
828	            [2, 5, 4, 20] => "telephoneNumber",
829	            [2, 5, 4, 42] => "givenName",
830	            [2, 5, 4, 43] => "initials",
831	            [2, 5, 4, 44] => "generationQualifier",
832	            [2, 5, 4, 46] => "dnQualifier",
833	            [2, 5, 4, 65] => "pseudonym",
834	            [0, 9, 2342, 19200300, 100, 1, 1] => "UID",
835	            [0, 9, 2342, 19200300, 100, 1, 25] => "DC",
836	            [1, 2, 840, 113549, 1, 9, 1] => "emailAddress",
837	            _ => return None,
838	        };
839	        Some(name)
840	    }
841	
842	    /// Decode a DirectoryString-style attribute value into UTF-8 text.
843	    fn decode_attribute_value(tag: u8, content: &[u8]) -> Result<String, String> {
844	        let s = match tag {
845	            0x0C => std::str::from_utf8(content)
846	                .map_err(|_| "invalid UTF-8 in UTF8String".to_string())?
847	                .to_string(),
848	            // ASCII-family strings: every byte is also its Unicode code point.
849	            0x12 | 0x13 | 0x16 | 0x1A => content.iter().map(|&b| b as char).collect(),
850	            // T.61 / GeneralString are conventionally treated as Latin-1 here.
851	            0x14 | 0x1B => content.iter().map(|&b| b as char).collect(),
852	            0x1E => {
853	                if content.len() % 2 != 0 {
854	                    return Err("odd-length BMPString".to_string());
855	                }
856	                let units: Vec<u16> = content
857	                    .chunks_exact(2)
858	                    .map(|c| u16::from_be_bytes([c[0], c[1]]))
859	                    .collect();
860	                char::decode_utf16(units.iter().copied())
861	                    .map(|r| r.map_err(|_| "unpaired surrogate in BMPString".to_string()))
862	                    .collect::<Result<String, _>>()?
863	            }
864	            0x1C => {
865	                if content.len() % 4 != 0 {
866	                    return Err("invalid UniversalString length".to_string());
867	                }
868	                let mut s = String::new();
869	                for c in content.chunks_exact(4) {
870	                    let cp = u32::from_be_bytes([c[0], c[1], c[2], c[3]]);
871	                    if (0xD800..=0xDFFF).contains(&cp) || cp > 0x10FFFF {
872	                        return Err("invalid code point in UniversalString".to_string());
873	                    }
874	                    s.push(char::from_u32(cp).unwrap());
875	                }
876	                s
877	            }
878	            _ => {
879	                return Err(format!(
880	                    "unsupported attribute value string type (tag 0x{tag:02X})"
881	                ))
882	            }
883	        };
884	        Ok(s)
885	    }
886	
887	    /// RFC 4514 value escaping; everything above the ASCII control range
888	    /// (including CJK text) passes through unchanged.
889	    fn escape_value(value: &str) -> String {
890	        let mut out = String::with_capacity(value.len());
891	        let last = value.chars().count().saturating_sub(1);
892	        for (i, c) in value.chars().enumerate() {
893	            let at_edge = i == 0 || i == last;
894	            let needs_backslash = matches!(c, ',' | '+' | '"' | '\\' | '<' | '>' | ';')
895	                || (at_edge && (c == ' ' || c == '#'));
896	            if needs_backslash {
897	                out.push('\\');
898	                out.push(c);
899	            } else if ('\0'..='\x1F').contains(&c) || c == '\x7F' {
900	                let mut buf = [0u8; 4];
901	                let b = c.encode_utf8(&mut buf).as_bytes()[0];
902	                write!(out, "\\{b:02X}").unwrap();
903	            } else {
904	                out.push(c);
905	            }
906	        }
907	        out
908	    }
909	
910	    fn format_time(tlv: Tlv) -> Result<String, String> {
911	        let (y, mo, d, h, mi, se) = match tlv.tag {
912	            TAG_UTC_TIME => {
913	                let c = tlv.content;
914	                if c.len() != 13 || c[12] != b'Z' {
915	                    return Err("UTCTime must be YYMMDDHHMMSSZ".to_string());
916	                }
917	                let digits = &c[..12];
918	                if !digits.iter().all(|b| b.is_ascii_digit()) {
919	                    return Err("non-numeric UTCTime".to_string());
920	                }
921	                let n = |a: usize, b: usize| -> u32 {
922	                    digits[a..=b].iter().fold(0, |acc, x| acc * 10 + (x - b'0') as u32)
923	                };
924	                let yy = n(0, 1);
925	                let year = if yy < 50 { 2000 + yy } else { 1900 + yy };
926	                (year as i32, n(2, 3), n(4, 5), n(6, 7), n(8, 9), n(10, 11))
927	            }
928	            TAG_GENERALIZED_TIME => {
929	                let c = tlv.content;
930	                if c.len() != 15 || c[14] != b'Z' {
931	                    return Err(
932	                        "GeneralizedTime must be YYYYMMDDHHMMSSZ in UTC".to_string()
933	                    );
934	                }
935	                let digits = &c[..14];
936	                if !digits.iter().all(|b| b.is_ascii_digit()) {
937	                    return Err("non-numeric GeneralizedTime".to_string());
938	                }
939	                let n = |a: usize, b: usize| -> u32 {
940	                    digits[a..=b].iter().fold(0, |acc, x| acc * 10 + (x - b'0') as u32)
941	                };
942	                (n(0, 3) as i32, n(4, 5), n(6, 7), n(8, 9), n(10, 11), n(12, 13))
943	            }
944	            other => return Err(format!("invalid time tag 0x{other:02X}")),
945	        };
946	        validate_datetime(y, mo, d, h, mi, se)?;
947	        Ok(format!("{y:04}-{mo:02}-{d:02}T{h:02}:{mi:02}:{se:02}Z"))
948	    }
949	
950	    fn validate_datetime(
951	        year: i32,
952	        month: u32,
953	        day: u32,
954	        hour: u32,
955	        minute: u32,
956	        second: u32,
957	    ) -> Result<(), String> {
958	        if !(1..=12).contains(&month) {
959	            return Err("invalid month in certificate time".to_string());
960	        }
961	        if hour > 23 || minute > 59 || second > 59 {
962	            return Err("invalid time of day in certificate time".to_string());
963	        }
964	        let leap = year % 4 == 0 && (year % 100 != 0 || year % 400 == 0);
965	        let days = [31, if leap { 29 } else { 28 }, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31];
966	        if day < 1 || day > days[(month - 1) as usize] {
967	            return Err("invalid day in certificate time".to_string());
968	        }
969	        Ok(())
970	    }
971	}
