79	#[test]
80	fn unknown_non_string_value_is_shown_as_full_der_hex() {
81	    // An OCTET STRING value (tag 0x04) is not text at all; the full encoding
82	    // still appears after '#'.
83	    let value = tlv(0x04, &[0x01, 0x02, 0x03]);
84	    let subject = name(&[rdn(&[atv(&[1, 2, 3, 4], &value)])]);
