124	#[test]
125	fn subject_and_issuer_render_independently() {
126	    // Each name reflects only its own attributes: distinct OID sets and value
127	    // encodings must never bleed across Subject/Issuer.
128	    let subject = name(&[
129	        rdn(&[atv_utf8(O, "测试")]),
130	        rdn(&[atv_utf8(CN, "subject.example")]),
131	    ]);
132	    // The issuer's multi-valued RDN follows DER SET OF order: the unknown
133	    // attribute's complete encoding is shorter, so it sorts before CN even
134	    // though CN would come first as a displayed name; display keeps the
135	    // encoding order.
136	    let issuer = name(&[rdn(&[
137	        atv_utf8(&[1, 2, 3, 4], "abc"),
138	        atv_utf8(CN, "Example CA"),
139	    ])]);
140	    let (out, _cert) = run_inspect("separate-names", &build_cert(&subject, &issuer));
141	
142	    assert_success(
143	        &out,
144	        "CN=subject.example,O=测试",
145	        "1.2.3.4=#0C03616263+CN=Example CA",
146	    );
147	}
