191	#[test]
192	fn text_hex_and_unknown_values_mix_without_splitting_multivalued_rdn() {
193	    // One multi-valued RDN mixes a text value (CN), a known attribute shown as
194	    // hex (postalAddress SEQUENCE) and an unknown attribute shown as hex
195	    // (1.2.3.4). The group stays joined with '+'; a preceding text RDN and a
196	    // repeated text CN in another RDN keep their order after reversal. The
197	    // members are encoded in DER SET OF order, which is decided here by the
198	    // outer SEQUENCE length and content bytes, not by attribute name: the
199	    // shortest member (unknown 1.2.3.4) sorts first, postalAddress next and
200	    // CN last — display preserves exactly that encoding order.
