325	    // A three-byte value encoded as 0x81 0x03 is not valid DER.
326	    let mut inner = oid(&[1, 2, 3, 4]);
327	    inner.extend_from_slice(&[0x0C, 0x81, 0x03, 0x61, 0x62, 0x63]);
328	    let subject = name(&[rdn(&[seq(&inner)])]);
329	    let issuer = simple_cn_name("Test CA");
330	    let (out, _cert) = run_inspect("nonminimal-len", &build_cert(&subject, &issuer));
331	
332	    assert_invalid_certificate(&out);
333	}
334	
335	#[test]
336	fn truncated_certificate_file_is_rejected() {
337	    // Bytes cut off the tail of an otherwise valid certificate: malformed
338	    // input, same failure contract.
339	    let subject = simple_cn_name("subject.example");
340	    let issuer = simple_cn_name("Test CA");
341	    let mut bytes = build_cert(&subject, &issuer);
342	    bytes.truncate(bytes.len() - 5);
343	    let (out, _cert) = run_inspect("truncated-cert", &bytes);
344	
345	    assert_invalid_certificate(&out);
346	}
347	
348	// ----- DER SET OF ordering inside multi-valued RDNs ------------------------
349	
350	#[test]
351	fn unsorted_subject_multivalued_rdn_is_rejected() {
352	    // O and CN in one RDN, encoded O-first: both members have the same outer
353	    // tag and length, and O's OID arc byte 0x0A is greater than CN's 0x03, so
354	    // the SET OF is not byte-sorted. This must fail as a corrupt certificate
355	    // and name the subject, never be printed or repaired by reordering the
356	    // members (alphabetically "CN" would sort first, which is exactly the
357	    // kind of display-name comparison that must not be used).
358	    let subject = name(&[rdn(&[atv_utf8(O, "y"), atv_utf8(CN, "x")])]);
359	    let issuer = simple_cn_name("Test CA");
360	    let (out, _cert) = run_inspect("bad-order-subject", &build_cert(&subject, &issuer));
361	
362	    assert_invalid_certificate(&out);
363	    let stderr = lossy(&out.stderr);
364	    assert!(
365	        stderr.contains("subject") && stderr.contains("order"),
366	        "reason must name the subject name and the ordering problem: {stderr}"
367	    );
368	}
369	
370	#[test]
371	fn unsorted_issuer_multivalued_rdn_is_rejected() {
372	    // Same violation in the issuer must be reported against the issuer name,
373	    // even though the subject is well-formed.
374	    let subject = simple_cn_name("subject.example");
375	    let issuer = name(&[rdn(&[atv_utf8(O, "y"), atv_utf8(CN, "x")])]);
376	    let (out, _cert) = run_inspect("bad-order-issuer", &build_cert(&subject, &issuer));
377	
378	    assert_invalid_certificate(&out);
379	    let stderr = lossy(&out.stderr);
380	    assert!(
381	        stderr.contains("issuer") && stderr.contains("order"),
382	        "reason must name the issuer name and the ordering problem: {stderr}"
383	    );
384	}
385	
386	#[test]
387	fn ordering_compares_encoding_content_not_attribute_text() {
388	    // The same unknown OID twice (identical dotted text) with values "b" and
389	    // "a": both complete encodings have equal tag and length, and the first
390	    // value byte 0x62 > 0x61, so "b" before "a" is out of DER order. Sorting
391	    // by attribute name or value text would call these identical or sort the
392	    // same way only by accident; this pins the comparison to encoding bytes.
393	    let subject = name(&[rdn(&[
394	        atv_utf8(&[1, 2, 3, 4], "b"),
395	        atv_utf8(&[1, 2, 3, 4], "a"),
396	    ])]);
397	    let issuer = simple_cn_name("Test CA");
398	    let (out, _cert) = run_inspect("bad-order-content", &build_cert(&subject, &issuer));
399	
400	    assert_invalid_certificate(&out);
401	}
402	
403	#[test]
404	fn ordering_compares_outer_length_before_value_text() {
405	    // CN="z" (complete ATV encoding 10 bytes) and 1.2.3.4="aaa" (12 bytes,
406	    // because its value is longer): DER compares tag, then the outer length
407	    // byte, so the shorter CN member sorts first even though the decoded
408	    // value text "aaa" would come well before "z". A comparison based on
409	    // decoded values would reject this legal certificate.
410	    let subject = name(&[rdn(&[
411	        atv_utf8(CN, "z"),
412	        atv_utf8(&[1, 2, 3, 4], "aaa"),
413	    ])]);
414	    let issuer = simple_cn_name("Test CA");
415	    let (out, _cert) = run_inspect("order-by-length", &build_cert(&subject, &issuer));
416	
417	    assert_success(&out, "CN=z+1.2.3.4=#0C03616161", "CN=Test CA");
418	
419	    // The reverse encoding is corrupt: the longer outer encoding must not
420	    // come first, regardless of the '#' text representation.
421	    let subject = name(&[rdn(&[
422	        atv_utf8(&[1, 2, 3, 4], "aaa"),
423	        atv_utf8(CN, "z"),
424	    ])]);
425	    let (out, _cert) = run_inspect("order-by-length-bad", &build_cert(&subject, &issuer));
426	    assert_invalid_certificate(&out);
427	}
428	
429	#[test]
430	fn each_rdn_is_checked_independently() {
431	    // Two RDNs in one name: the first (outermost) group is fine, a later
432	    // group carries O-before-CN out of order (OID arc 0x0A > 0x03). The
433	    // whole name must be rejected rather than treated as one set or checked
434	    // only on a group of the checker's choosing.
435	    let subject = name(&[
436	        rdn(&[atv_utf8(C, "CN")]),
437	        rdn(&[atv_utf8(O, "y"), atv_utf8(CN, "x")]),
438	    ]);
439	    let issuer = simple_cn_name("Test CA");
440	    let (out, _cert) = run_inspect("bad-order-second-rdn", &build_cert(&subject, &issuer));
441	
442	    assert_invalid_certificate(&out);
443	    assert!(lossy(&out.stderr).contains("subject"));
444	}
445	
446	#[test]
447	fn identical_adjacent_members_are_allowed_and_not_deduplicated() {
448	    // Two members with byte-for-byte identical complete encodings compare
449	    // equal and therefore satisfy the sorted SET OF rule; both must still
450	    // appear in the output (no merging, no false ordering failure).
451	    let subject = name(&[rdn(&[
452	        atv_utf8(CN, "dup"),
453	        atv_utf8(CN, "dup"),
454	    ])]);
455	    let issuer = simple_cn_name("Test CA");
456	    let (out, _cert) = run_inspect("dup-members", &build_cert(&subject, &issuer));
457	
458	    assert_success(&out, "CN=dup+CN=dup", "CN=Test CA");
459	}
460	
461	#[test]
462	fn single_attribute_rdn_always_satisfies_set_ordering() {
463	    // A SET OF with one member is trivially sorted, whatever the attribute
464	    // and value encodings are.
465	    let subject = name(&[
466	        rdn(&[atv_utf8(C, "CN")]),
467	        rdn(&[atv_utf8(O, "org")]),
468	        rdn(&[atv_utf8(CN, "host")]),
469	    ]);
470	    let issuer = simple_cn_name("Test CA");
471	    let (out, _cert) = run_inspect("single-member-rdns", &build_cert(&subject, &issuer));
472	
473	    assert_success(&out, "CN=host,O=org,C=CN", "CN=Test CA");
474	}
475	
476	// ----- CLI contract: usage, version and unreadable files ------------------
477	
478	#[test]
479	fn version_flag_keeps_its_output() {
480	    let out = Command::new(env!("CARGO_BIN_EXE_chainview"))
481	        .arg("--version")
482	        .output()
483	        .expect("running chainview");
484	    assert_eq!(out.status.code(), Some(0));
485	    assert!(out.stderr.is_empty());
486	    assert_eq!(lossy(&out.stdout), "chainview 0.1.0\n");
487	}
488	
489	#[test]
490	fn missing_path_is_a_usage_error() {
491	    let out = Command::new(env!("CARGO_BIN_EXE_chainview"))
492	        .arg("inspect")
493	        .output()
494	        .expect("running chainview");
495	    assert_eq!(out.status.code(), Some(2));
496	    assert!(out.stdout.is_empty());
497	    assert_eq!(
498	        lossy(&out.stderr),
499	        "Usage: chainview inspect <DER-FILE>\n       chainview --version\n"
500	    );
501	}
502	
503	#[test]
504	fn unreadable_file_keeps_its_error_contract() {
505	    let missing = std::env::temp_dir().join("chainview-name-test-definitely-missing.der");
506	    let _ = fs::remove_file(&missing);
507	    let out = Command::new(env!("CARGO_BIN_EXE_chainview"))
508	        .arg("inspect")
509	        .arg(&missing)
510	        .output()
511	        .expect("running chainview");
512	    assert_eq!(out.status.code(), Some(2));
513	    assert!(out.stdout.is_empty());
514	    let stderr = lossy(&out.stderr);
515	    assert!(
516	        stderr.starts_with(&format!(
517	            "chainview: cannot read certificate file '{}': ",
518	            missing.display()
519	        )),
520	        "unexpected stderr: {stderr}"
521	    );
522	}
523	
524	// ----- Assertions / process plumbing --------------------------------------
525	
526	fn assert_success(out: &Output, subject: &str, issuer: &str) {
527	    assert_eq!(out.status.code(), Some(0), "stderr={}", lossy(&out.stderr));
528	    assert!(out.stderr.is_empty(), "stderr={}", lossy(&out.stderr));
529	    assert_eq!(
530	        lossy(&out.stdout),
531	        format!(
532	            "Subject: {subject}\n\
533	             Issuer: {issuer}\n\
534	             Serial Number: {FIXED_SERIAL}\n\
535	             Not Before: {FIXED_NOT_BEFORE}\n\
536	             Not After: {FIXED_NOT_AFTER}\n"
537	        )
538	    );
539	}
540	
541	/// Every malformed-input case shares the documented contract: exit code 2,
542	/// nothing on stdout (so no name field can be printed before the error is
543	/// noticed), and the fixed invalid-certificate message prefix on stderr.
544	fn assert_invalid_certificate(out: &Output) {
545	    assert_eq!(
546	        out.status.code(),
547	        Some(2),
548	        "stdout={} stderr={}",
549	        lossy(&out.stdout),
550	        lossy(&out.stderr)
551	    );
552	    assert!(
553	        out.stdout.is_empty(),
554	        "stdout must be empty on failure, got: {}",
555	        lossy(&out.stdout)
556	    );
557	    let stderr = lossy(&out.stderr);
558	    assert!(
559	        stderr.starts_with("chainview: invalid DER certificate: "),
560	        "unexpected stderr: {stderr}"
561	    );
562	    // A non-empty reason after the fixed prefix.
563	    assert!(
564	        stderr["chainview: invalid DER certificate: ".len()..].trim().len() > 1,
565	        "missing error reason in stderr: {stderr}"
566	    );
567	}
568	
569	fn lossy(bytes: &[u8]) -> String {
570	    String::from_utf8_lossy(bytes).into_owned()
571	}
572	
573	fn run_inspect(tag: &str, data: &[u8]) -> (Output, TempCert) {
574	    let cert = TempCert::new(tag, data);
575	    let output = Command::new(env!("CARGO_BIN_EXE_chainview"))
576	        .arg("inspect")
577	        .arg(&cert.path)
578	        .output()
579	        .expect("running chainview");
580	    (output, cert)
581	}
582	
583	struct TempCert {
584	    path: PathBuf,
585	}
586	
587	impl TempCert {
588	    fn new(tag: &str, data: &[u8]) -> Self {
589	        static COUNTER: AtomicU64 = AtomicU64::new(0);
590	        let unique = COUNTER.fetch_add(1, Ordering::Relaxed);
591	        let path = std::env::temp_dir().join(format!(
592	            "chainview-name-test-{}-{tag}-{unique}.der",
593	            std::process::id()
594	        ));
595	        fs::write(&path, data).expect("writing temp certificate");
596	        TempCert { path }
597	    }
598	}
599	
600	impl Drop for TempCert {
601	    fn drop(&mut self) {
602	        let _ = fs::remove_file(&self.path);
603	    }
604	}
605	
606	// ----- Certificate / DER construction -------------------------------------
607	//
608	// Only the structural pieces needed here. Lengths are always emitted in the
609	// minimal DER form, except where a test injects raw bytes to exercise
610	// rejection of non-minimal or truncated encodings.
611	
612	fn simple_cn_name(cn: &str) -> Vec<u8> {
613	    name(&[rdn(&[atv_utf8(CN, cn)])])
614	}
615	
616	/// Assemble a complete, parseable v1 DER certificate with fixed serial,
617	/// validity and key material around the supplied Subject/Issuer names.
618	fn build_cert(subject: &[u8], issuer: &[u8]) -> Vec<u8> {
619	    let serial = tlv(0x02, &[0x0E, 0x8A, 0x4C, 0x2F, 0x9B, 0x17, 0xD6, 0x03]);
620	    let validity = seq(&concat(&[
621	        &tlv(0x17, b"260115093000Z"), // UTCTime 2026-01-15T09:30:00Z
622	        &tlv(0x17, b"270115093000Z"), // UTCTime 2027-01-15T09:30:00Z
623	    ]));
624	    let spki = seq(&concat(&[
625	        &seq(&concat(&[&oid(&[1, 2, 840, 113549, 1, 1, 1]), &tlv(0x05, &[])])),
626	        &tlv(0x03, &[0x00, 0x01, 0x00]), // BIT STRING, zero unused bits
627	    ]));
628	
629	    let tbs = seq(&concat(&[
630	        &serial,
631	        &signature_algorithm(),
632	        issuer,
633	        &validity,
634	        subject,
635	        &spki,
636	    ]));
637	    seq(&concat(&[&tbs, &signature_algorithm(), &tlv(0x03, &[0x00])]))
638	}
639	
640	fn signature_algorithm() -> Vec<u8> {
641	    // sha256WithRSAEncryption with explicit NULL parameters.
642	    seq(&concat(&[&oid(&[1, 2, 840, 113549, 1, 1, 11]), &tlv(0x05, &[])]))
643	}
644	
645	fn name(rdns: &[Vec<u8>]) -> Vec<u8> {
646	    tlv(
647	        0x30,
648	        &concat(&rdns.iter().map(Vec::as_slice).collect::<Vec<_>>()),
649	    )
650	}
651	
652	fn rdn(atvs: &[Vec<u8>]) -> Vec<u8> {
653	    tlv(
654	        0x31,
655	        &concat(&atvs.iter().map(Vec::as_slice).collect::<Vec<_>>()),
656	    )
657	}
658	
659	/// AttributeTypeAndValue ::= SEQUENCE { type OID, value ANY } — `value` is the
660	/// complete DER TLV of the value.
661	fn atv(arcs: &[u64], value: &[u8]) -> Vec<u8> {
662	    seq(&concat(&[&oid(arcs), value]))
663	}
664	
665	fn atv_utf8(arcs: &[u64], text: &str) -> Vec<u8> {
666	    atv(arcs, &tlv(0x0C, text.as_bytes()))
667	}
668	
669	fn oid(arcs: &[u64]) -> Vec<u8> {
670	    assert!(arcs.len() >= 2);
671	    let mut content = oid_arc(arcs[0] * 40 + arcs[1]);
672	    for &arc in &arcs[2..] {
673	        content.extend_from_slice(&oid_arc(arc));
674	    }
675	    tlv(0x06, &content)
676	}
677	
678	fn oid_arc(mut value: u64) -> Vec<u8> {
679	    let mut out = vec![(value % 128) as u8];
680	    value /= 128;
681	    while value > 0 {
682	        out.push(0x80 | (value % 128) as u8);
683	        value /= 128;
684	    }
685	    out.reverse();
686	    out
687	}
688	
689	fn seq(content: &[u8]) -> Vec<u8> {
690	    tlv(0x30, content)
691	}
692	
693	fn tlv(tag: u8, content: &[u8]) -> Vec<u8> {
694	    let mut out = vec![tag];
695	    out.extend_from_slice(&der_len(content.len()));
696	    out.extend_from_slice(content);
697	    out
698	}
699	
700	fn der_len(n: usize) -> Vec<u8> {
701	    if n < 0x80 {
702	        vec![n as u8]
703	    } else {
704	        let mut body = Vec::new();
705	        let mut v = n;
706	        while v > 0 {
707	            body.push((v & 0xFF) as u8);
708	            v >>= 8;
709	        }
710	        body.reverse();
711	        let mut out = vec![0x80 | body.len() as u8];
712	        out.extend_from_slice(&body);
713	        out
714	    }
715	}
716	
717	fn concat(parts: &[&[u8]]) -> Vec<u8> {
718	    let mut out = Vec::new();
719	    for part in parts {
720	        out.extend_from_slice(part);
721	    }
722	    out
723	}
724	
725	fn hex(bytes: &[u8]) -> String {
726	    let mut s = String::with_capacity(bytes.len() * 2);
727	    for b in bytes {
728	        use std::fmt::Write;
729	        write!(s, "{b:02X}").unwrap();
730	    }
731	    s
732	}
